const lessons=[{"sentences":[{"speaker":"A","text":"We should plan our weekend walking trip because the weather forecast looks quite changeable.","position":1,"audioStartSeconds":0,"audioEndSeconds":5.443125},{"speaker":"B","text":"Although the sun might shine this morning, heavy rain is expected by tomorrow afternoon.","position":2,"audioStartSeconds":5.643125,"audioEndSeconds":11.150708333333334},{"speaker":"A","text":"If we want to avoid getting soaked, we need a route that offers plenty of shelter.","position":3,"audioStartSeconds":11.350708333333333,"audioEndSeconds":16.506125},{"speaker":"B","text":"The valley path has lots of thick trees when you walk through the lower section.","position":4,"audioStartSeconds":16.706125,"audioEndSeconds":21.358958333333334},{"speaker":"A","text":"That sounds sensible, but remember that my cousin Mark is joining us this time.","position":5,"audioStartSeconds":21.558958333333333,"audioEndSeconds":26.778041666666667},{"speaker":"B","text":"Is he still recovering from his ankle injury after his recent holiday accident?","position":6,"audioStartSeconds":26.978041666666666,"audioEndSeconds":32.222875},{"speaker":"A","text":"He can walk normally now, although steep hills still cause him some slight discomfort.","position":7,"audioStartSeconds":32.422875,"audioEndSeconds":37.93833333333333},{"speaker":"B","text":"The valley route stays mostly flat because it follows the river along the bottom.","position":8,"audioStartSeconds":38.138333333333335,"audioEndSeconds":43.048125},{"speaker":"A","text":"That is perfect because it will not put too much pressure on his healing ankle.","position":9,"audioStartSeconds":43.248125,"audioEndSeconds":48.145041666666664},{"speaker":"B","text":"We could also try the ridge trail if everyone prefers a better view from the top.","position":10,"audioStartSeconds":48.34504166666667,"audioEndSeconds":53.203291666666665},{"speaker":"A","text":"The ridge is completely exposed to strong winds and has no protection if storms arrive.","position":11,"audioStartSeconds":53.40329166666667,"audioEndSeconds":58.91875},{"speaker":"B","text":"You are completely right since safety should always come first when conditions are poor.","position":12,"audioStartSeconds":59.11875,"audioEndSeconds":64.51825},{"speaker":"A","text":"Let us stick with the sheltered valley path since it keeps us dry and safe.","position":13,"audioStartSeconds":64.71825,"audioEndSeconds":69.31875},{"speaker":"B","text":"We should also check our waterproof jackets and pack some warm extra layers.","position":14,"audioStartSeconds":69.51875,"audioEndSeconds":74.32545833333333},{"speaker":"A","text":"I will send Mark a quick message tonight to confirm our starting time and location.","position":15,"audioStartSeconds":74.52545833333333,"audioEndSeconds":79.747125},{"speaker":"B","text":"Meet me at the central station cafe on Saturday morning before we catch the bus.","position":16,"audioStartSeconds":79.947125,"audioEndSeconds":85.21533333333333}],"questions":[{"prompt":"What is the main purpose of the conversation?","options":["To check the local weather forecast.","To choose a suitable walking route.","To invite Mark to a hiking trip."],"answer":"B","evidenceSentence":1,"evidence":"We should plan our weekend walking trip","explanation":"Hai nhân vật bàn bạc để chọn một tuyến đường đi bộ thích hợp cho cuối tuần."},{"prompt":"What weather condition are the speakers trying to avoid?","options":["Heavy rain.","Strong winds.","Morning sun."],"answer":"A","evidenceSentence":2,"evidence":"heavy rain is expected by tomorrow afternoon","explanation":"Họ lo ngại cơn mưa lớn sắp tới vào chiều mai."},{"prompt":"Why is Mark's participation important for their decision?","options":["He has a foot injury.","He prefers steep hills.","He dislikes forest paths."],"answer":"A","evidenceSentence":6,"evidence":"recovering from his ankle injury","explanation":"Mark mới chấn thương cổ chân nên họ phải chọn đường bằng phẳng."},{"prompt":"Why was the ridge trail rejected?","options":["It is too far away.","It lacks shelter from storms.","It has no good views."],"answer":"B","evidenceSentence":11,"evidence":"completely exposed to strong winds and has no protection","explanation":"Đường sống núi không có chỗ trú ẩn khi có bão và gió mạnh."},{"prompt":"What do the speakers finally decide to do?","options":["Cancel the walking trip.","Take the ridge trail.","Use the valley path."],"answer":"C","evidenceSentence":13,"evidence":"stick with the sheltered valley path","explanation":"Họ quyết định chọn lối đi trong thung lũng có mái che."},{"prompt":"What will speaker A do tonight?","options":["Send Mark a message.","Buy waterproof jackets.","Check the bus timetable."],"answer":"A","evidenceSentence":15,"evidence":"send Mark a quick message tonight","explanation":"Speaker A sẽ nhắn tin cho Mark tối nay để xác nhận thời gian và địa điểm."}]}];const cards=[...document.querySelectorAll('article')];let stopping=null,stoppingAudio=null;
    document.addEventListener('play',event=>{if(event.target.tagName!=='AUDIO')return;document.querySelectorAll('audio').forEach(a=>{if(a!==event.target)a.pause()})},true);
    document.querySelectorAll('[data-filter]').forEach(button=>button.onclick=()=>{let count=0;cards.forEach(c=>{c.hidden=button.dataset.filter!=='ALL'&&c.dataset.goal!==button.dataset.filter;if(!c.hidden)count++;else c.querySelector('audio').pause()});document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',b===button));document.querySelector('#filter-status').textContent='Đang hiển thị '+count+' bài.'});
    const normal=value=>value.trim().toLowerCase().replace(/\s+/g,' ');
    document.querySelectorAll('[data-check]').forEach(button=>button.onclick=()=>{const i=Number(button.dataset.check);let score=0;lessons[i].questions.forEach((q,n)=>{const value=normal(document.getElementById('answer-'+i+'-'+n).value);if([q.answer,...(q.accepted||[])].some(a=>normal(a)===value))score++});document.getElementById('result-'+i).textContent=score+'/'+lessons[i].questions.length+' câu đúng. Mở phần đáp án để xem giải thích.'});
    document.querySelectorAll('[data-segment]').forEach(button=>button.onclick=async()=>{if(stopping)stopping();const [i,n]=button.dataset.segment.split(',').map(Number),audio=cards[i].querySelector('audio'),s=lessons[i].sentences[n];audio.currentTime=s.audioStartSeconds;const stop=()=>{stopping=null;stoppingAudio=null;audio.removeEventListener('timeupdate',check);audio.pause()},check=()=>{if(audio.currentTime>=s.audioEndSeconds)stop()};stopping=stop;stoppingAudio=audio;audio.addEventListener('timeupdate',check);try{await audio.play()}catch(_){stop();document.getElementById('result-'+i).textContent='Không phát được audio. Hãy dùng nút tải WAV để nghe.'}});
    document.querySelectorAll('audio').forEach(audio=>audio.addEventListener('pause',()=>{if(audio.paused&&stoppingAudio===audio&&stopping)stopping()}));
const authStatus=document.querySelector('#auth-status');
async function initializeAudio(){
 try{
  const response=await fetch('/api/auth/me',{credentials:'same-origin'});
  if(response.status===401){authStatus.hidden=false;authStatus.innerHTML='Đăng nhập để nghe audio. <a href="/login?next=%2Fcatalog%3Fgoal%3DALL">Đăng nhập</a> rồi mở bài từ thư viện bằng nút “Nghe toàn bài & làm câu hỏi”.';return}
  if(!response.ok)throw Error('account');
  document.querySelectorAll('audio').forEach(audio=>{audio.src=audio.dataset.src;audio.preload='none';audio.hidden=false});
  document.querySelectorAll('[data-segment]').forEach(button=>button.disabled=false);
  document.querySelectorAll('a[download]').forEach(link=>link.hidden=false);
 }catch(_){authStatus.hidden=false;authStatus.textContent='Không kiểm tra được đăng nhập. Hãy tải lại trang để thử lại.'}
}
initializeAudio();
